function tau_M_ref = mfun_cvc_speed_controller(enable, w_M, tau_M, w_M_ref, p)
%MFUN_CVC_SPEED_CONTROLLER Block SpeedController of the control system.
%   SpeedController of motulator. Generated by motulator_export from the MATLAB port of
%   motulator and called by the MATLAB Function block of the Simulink model, which adds
%   its folder to the MATLAB path. The parameters are the fields of the struct p (from
%   the mask, [] as NaN). The state is in persistent variables, of which each MATLAB
%   Function block has its own copy. The inputs without direct feedthrough come through
%   unit delays, so the update of the state with them is done at the next call.
persistent self pending
if isempty(self)
    % No torque limit without tau_M_max
    tau_M_max = p.tau_M_max;
    if isnan(tau_M_max)
        tau_M_max = Inf;
    end
    self = speed_controller(p.J, p.alpha_s, p.alpha_i, tau_M_max);
    pending = false;
end
% Update of the previous sampling period with its inputs (the inputs
% enable, tau_M through unit delays)
if pending
    % The limited torque reference ref.tau_M (anti-windup), not updated while
    % the gates are blocked
    if enable > 0
        self = pi_update(self, p.T_s, tau_M);
    end
end
pending = true;
% Torque reference
[self, tau_M_ref] = pi_compute_output(self, w_M_ref, w_M, 0);
end

function y = clip(value, min_value, max_value)
%CLIP Limit the value into the range [min_value, max_value].
y = max(min(value, max_value), min_value);
end

function self = pi_init(k_p, k_t, alpha_i, u_max)
%PI_INIT 2DOF PI controller (PIController), alpha_i being the inverse of the
%   integration time.
self = struct('k_p', k_p, 'k_t', k_t, 'alpha_i', alpha_i, 'u_max', u_max, ...
    'u_i', 0, 'v', 0);
end

function [self, u] = pi_compute_output(self, y_ref, y, u_ff)
%PI_COMPUTE_OUTPUT Limited controller output.
% Estimate of a disturbance input
self.v = self.u_i - (self.k_p - self.k_t)*y + u_ff;
u = self.k_t*(y_ref - y) + self.v;
% Limit the controller output
u = clip(u, -self.u_max, self.u_max);
end

function self = pi_update(self, T_s, u)
%PI_UPDATE Update the integral state with the realized (limited) output u.
self.u_i = self.u_i + T_s*self.alpha_i*(u - self.v);
end

function ctrl = speed_controller(J, alpha_s, alpha_i, tau_M_max)
%SPEED_CONTROLLER 2DOF PI speed controller (SpeedController); alpha_i = NaN means
%   alpha_s.
if isnan(alpha_i)
    alpha_i = alpha_s;
end
k_p = (alpha_s + alpha_i)*J;
k_i = alpha_s*alpha_i*J;
k_t = alpha_s*J;
ctrl = pi_init(k_p, k_t, k_i/k_t, tau_M_max);
end
